macro_rules! partition_in_blocks {
    () => {
        # [doc = " Partitions `v` into elements smaller than `pivot`, followed by elements greater than or equal"] # [doc = " to `pivot`."] # [doc = ""] # [doc = " Returns the number of elements smaller than `pivot`."] # [doc = ""] # [doc = " Partitioning is performed block-by-block in order to minimize the cost of branching operations."] # [doc = " This idea is presented in the [BlockQuicksort][pdf] paper."] # [doc = ""] # [doc = " [pdf]: https://drops.dagstuhl.de/opus/volltexte/2016/6389/pdf/LIPIcs-ESA-2016-38.pdf"] fn partition_in_blocks < T , F > (v : & mut [T] , pivot : & T , is_less : & F) -> usize where F : Fn (& T , & T) -> bool , { const BLOCK : usize = 128 ; let mut l = v . as_mut_ptr () ; let mut block_l = BLOCK ; let mut start_l = ptr :: null_mut () ; let mut end_l = ptr :: null_mut () ; let mut offsets_l = [MaybeUninit :: < u8 > :: uninit () ; BLOCK] ; let mut r = unsafe { l . add (v . len ()) } ; let mut block_r = BLOCK ; let mut start_r = ptr :: null_mut () ; let mut end_r = ptr :: null_mut () ; let mut offsets_r = [MaybeUninit :: < u8 > :: uninit () ; BLOCK] ; fn width < T > (l : * mut T , r : * mut T) -> usize { assert ! (size_of ::< T > () > 0) ; (r as usize - l as usize) / size_of :: < T > () } loop { let is_done = width (l , r) <= 2 * BLOCK ; if is_done { let mut rem = width (l , r) ; if start_l < end_l || start_r < end_r { rem -= BLOCK ; } if start_l < end_l { block_r = rem ; } else if start_r < end_r { block_l = rem ; } else { block_l = rem / 2 ; block_r = rem - block_l ; } debug_assert ! (block_l <= BLOCK && block_r <= BLOCK) ; debug_assert ! (width (l , r) == block_l + block_r) ; } if start_l == end_l { start_l = offsets_l . as_mut_ptr () as * mut u8 ; end_l = start_l ; let mut elem = l ; for i in 0 .. block_l { unsafe { * end_l = i as u8 ; end_l = end_l . add (! is_less (& * elem , pivot) as usize) ; elem = elem . add (1) ; } } } if start_r == end_r { start_r = offsets_r . as_mut_ptr () as * mut u8 ; end_r = start_r ; let mut elem = r ; for i in 0 .. block_r { unsafe { elem = elem . sub (1) ; * end_r = i as u8 ; end_r = end_r . add (is_less (& * elem , pivot) as usize) ; } } } let count = cmp :: min (width (start_l , end_l) , width (start_r , end_r)) ; if count > 0 { macro_rules ! left { () => { l . add (usize :: from (* start_l)) } ; } macro_rules ! right { () => { r . sub (usize :: from (* start_r) + 1) } ; } unsafe { let tmp = ptr :: read (left ! ()) ; ptr :: copy_nonoverlapping (right ! () , left ! () , 1) ; for _ in 1 .. count { start_l = start_l . add (1) ; ptr :: copy_nonoverlapping (left ! () , right ! () , 1) ; start_r = start_r . add (1) ; ptr :: copy_nonoverlapping (right ! () , left ! () , 1) ; } ptr :: copy_nonoverlapping (& tmp , right ! () , 1) ; mem :: forget (tmp) ; start_l = start_l . add (1) ; start_r = start_r . add (1) ; } } if start_l == end_l { l = unsafe { l . add (block_l) } ; } if start_r == end_r { r = unsafe { r . sub (block_r) } ; } if is_done { break ; } } if start_l < end_l { debug_assert_eq ! (width (l , r) , block_l) ; while start_l < end_l { unsafe { end_l = end_l . sub (1) ; ptr :: swap (l . add (usize :: from (* end_l)) , r . sub (1)) ; r = r . sub (1) ; } } width (v . as_mut_ptr () , r) } else if start_r < end_r { debug_assert_eq ! (width (l , r) , block_r) ; while start_r < end_r { unsafe { end_r = end_r . sub (1) ; ptr :: swap (l , r . sub (usize :: from (* end_r) + 1)) ; l = l . add (1) ; } } width (v . as_mut_ptr () , l) } else { width (v . as_mut_ptr () , l) } }
    };
}

partition_in_blocks!();